
const sites=[{"id": "site_a", "name": "가상 현장 A", "english": "SITE A", "city": "예시 도시", "country": "예시 국가", "count": 3, "lat": 15, "lon": -80, "href": "00-site-overview.html"}, {"id": "site-b", "name": "가상 현장 B", "english": "SITE B", "city": "예시 도시", "country": "예시 국가", "count": 2, "lat": -10, "lon": -40, "href": "index.html?site=site-b"}, {"id": "site-c", "name": "가상 현장 C", "english": "SITE C", "city": "예시 도시", "country": "예시 국가", "count": 0, "lat": 30, "lon": 20, "href": "index.html?site=site-c"}, {"id": "site-d", "name": "가상 현장 D", "english": "SITE D", "city": "예시 도시", "country": "예시 국가", "lat": -25, "lon": 60, "count": 0, "reference": true, "href": "index.html?site=site-d"}, {"id": "site-e", "name": "가상 현장 E", "english": "SITE E", "city": "예시 도시", "country": "예시 국가", "lat": 5, "lon": 100, "count": 0, "reference": true, "href": "index.html?site=site-e"}, {"id": "site-f", "name": "가상 현장 F", "english": "SITE F", "city": "예시 도시", "country": "예시 국가", "lat": 40, "lon": 130, "count": 0, "reference": true, "href": "index.html?site=site-f"}, {"id": "site-g", "name": "가상 현장 G", "english": "SITE G", "city": "예시 도시", "country": "예시 국가", "lat": 0, "lon": -120, "count": 0, "reference": true, "href": "index.html?site=site-g"}, {"id": "site-h", "name": "가상 현장 H", "english": "SITE H", "city": "예시 도시", "country": "예시 국가", "lat": -35, "lon": 150, "count": 0, "reference": true, "href": "index.html?site=site-h"}, {"id": "site-i", "name": "가상 현장 I", "english": "SITE I", "city": "예시 도시", "country": "예시 국가", "lat": 25, "lon": -10, "count": 0, "reference": true, "href": "index.html?site=site-i"}, {"id": "site-j", "name": "가상 현장 J", "english": "SITE J", "city": "예시 도시", "country": "예시 국가", "lat": -5, "lon": 70, "count": 0, "reference": true, "href": "index.html?site=site-j"}];let selected=new URLSearchParams(location.search).get('site')||'site_a',picking=false,pendingLocation=null;
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const dialog=document.querySelector('#new-site-dialog');function openDialog(){dialog.style.display='flex';}function closeDialog(){dialog.style.display='none';}
function render(){document.querySelector('#total-sites').textContent=sites.length;const s=sites.find(x=>x.id===selected)||sites[0];selected=s.id;
document.querySelector('#map-markers').innerHTML=sites.map((site,i)=>{const x=(site.lon+180)*1000/360,y=(90-site.lat)*500/180;const pos=site.labelPos||(i===0?[87,86]:i===1?[74,199]:i===2?[253,121]:[x+15,y-36]);return '<g role="button" tabindex="0" aria-label="'+esc(site.name)+' 매장 선택" class="map-site '+(selected===site.id?'selected':'')+(site.count?' needs-review':'')+'" data-map-site="'+site.id+'"><path class="marker-line" d="M'+x+','+y+'L'+(pos[0]+54)+','+(pos[1]+17)+'"/><circle class="marker-dot" cx="'+x+'" cy="'+y+'" r="4.5"/><rect class="label" x="'+pos[0]+'" y="'+pos[1]+'" width="115" height="34" rx="5"/><text x="'+(pos[0]+12)+'" y="'+(pos[1]+22)+'">'+esc(site.name)+'</text><text class="count" text-anchor="middle" x="'+(pos[0]+94)+'" y="'+(pos[1]+22)+'">'+(site.count?'('+site.count+')':(site.reference?'·':'✓'))+'</text></g>';}).join('');
document.querySelectorAll('[data-map-site]').forEach(e=>{e.onclick=ev=>{if(picking)return;ev.stopPropagation();selected=e.dataset.mapSite;render();};e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){selected=e.dataset.mapSite;render();}};});
document.querySelector('#selected-name').textContent=s.name;document.querySelector('#selected-city').textContent=s.city+' · '+s.country;document.querySelector('#selected-status').textContent=s.reference?'위치 참고':s.count?'검토 '+s.count+'건':'대기 항목 없음';document.querySelector('#selected-status').className='tag '+(s.reference?'neutral':s.count?'request':'confirmed');document.querySelector('#selected-week').textContent=s.id==='site_a'?'제7주':'자료 연결 전';document.querySelector('#selected-gantt').textContent=s.id==='site_a'?'79개 작업':'미연결';document.querySelector('#selected-hint').textContent=s.id==='site_a'?'피팅룸 조명의 재제출 사진과 스프링클러 기간 요청을 확인해 주세요.':s.reference?'최근 개점 매장 · '+s.opened+' / 위치 참고용입니다. 공사 일정과 검토 데이터는 연결하지 않았습니다.':'매장을 선택했습니다. 공정표를 연결하면 매장별 일정과 보고서를 확인할 수 있습니다.';document.querySelector('#open-site').href=s.id==='site_a'?'00-site-overview.html':'#';document.querySelector('#open-site').textContent=s.id==='site_a'?'매장 열기 →':'공정표 연결';document.querySelector('.selected-photo').style.display=s.id==='site_a'?'block':'none';
}
document.querySelector('#add-site').onclick=openDialog;document.querySelector('.site-add').onclick=e=>{e.preventDefault();openDialog();};document.querySelector('#close-dialog').onclick=closeDialog;document.querySelector('#cancel-dialog').onclick=closeDialog;document.querySelector('#choose-location').onclick=()=>{closeDialog();picking=true;document.querySelector('#map-stage').classList.add('picking');document.querySelector('#picking-hint').style.display='block';};
document.querySelector('#world-map').onclick=e=>{if(!picking)return;const svg=e.currentTarget,p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const local=p.matrixTransform(svg.getScreenCTM().inverse());pendingLocation={lon:local.x/1000*360-180,lat:90-local.y/500*180};picking=false;document.querySelector('#map-stage').classList.remove('picking');document.querySelector('#picking-hint').style.display='none';document.querySelector('#location-status').textContent='위치 선택 완료';openDialog();};
document.querySelector('#new-site-form').onsubmit=e=>{e.preventDefault();if(!pendingLocation){document.querySelector('#form-error').textContent='지도에서 매장 위치를 선택해 주세요.';return;}const name=document.querySelector('#site-name').value.trim(),country=document.querySelector('#site-country').value.trim(),city=document.querySelector('#site-city').value.trim();if(!name||!country||!city)return;const site={id:'new-'+sites.length,name,english:city,city,country,count:0,managerId:document.querySelector('#site-manager-id').value.trim(),managerContact:document.querySelector('#site-manager-contact').value.trim(),camera:document.querySelector('#site-camera').value.trim(),...pendingLocation};sites.push(site);selected=site.id;const a=document.createElement('a');a.className='site';a.href='#';a.dataset.siteLink=site.id;a.innerHTML='<span class="site-name">'+esc(name)+'<small>'+esc(city)+'</small></span><span class="site-check">✓</span>';a.onclick=ev=>{ev.preventDefault();selected=site.id;render();};document.querySelector('.site-list').append(a);closeDialog();render();document.querySelector('#toast').textContent='시안: 새 매장을 추가했습니다. 실제 저장은 하지 않습니다.';document.querySelector('#toast').style.display='block';setTimeout(()=>document.querySelector('#toast').style.display='none',2500);};
document.querySelector('#open-site').onclick=e=>{if(selected==='site_a')return;e.preventDefault();document.querySelector('#site-gantt').click();};render();if(new URLSearchParams(location.search).has('add'))openDialog();
